from collections import OrderedDict

def cache_sim(capacity, ttl, ops):
    cache = OrderedDict()  # key -> [value, write_time]
    results = []

    def is_expired(key, t):
        if key not in cache:
            return True
        _, wt = cache[key]
        return t >= wt + ttl

    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op
            if key in cache:
                if is_expired(key, t):
                    del cache[key]
            if key in cache:
                cache[key] = [value, t]
                cache.move_to_end(key)
            else:
                if len(cache) >= capacity:
                    # evict LRU (need to skip? no, just evict oldest regardless of expiry)
                    cache.popitem(last=False)
                cache[key] = [value, t]
                cache.move_to_end(key)
        elif op[0] == 'get':
            _, t, key = op
            if key in cache and not is_expired(key, t):
                value = cache[key][0]
                cache.move_to_end(key)
                results.append(value)
            else:
                if key in cache:
                    del cache[key]
                results.append(-1)

    return results

